namespace OptunaSharp.Internal;

/// <summary>
///     Joe-Kuo <c>new-joe-kuo-6.21201</c> direction-number data for the Sobol' sequence, the first
///     <see cref="MaxDim" /> dimensions (identical to <c>scipy.stats.qmc.Sobol</c>'s embedded table,
///     which OptunaSharp's <see cref="QuasiMonteCarlo" /> must match). Packed little-endian as
///     <c>Poly</c> (1024 uint16 primitive polynomials) followed by the flattened initial m-values
///     (one dimension's <c>degree</c> values after another; <c>degree = bit_length(poly) - 1</c>).
///     Reference: rustuna <c>qmc/sobol/direction_numbers.rs</c>.
/// </summary>
internal static class SobolDirectionNumbers
{
    /// <summary>Number of dimensions the embedded table supports (matches rustuna).</summary>
    internal const int MaxDim = 1024;

    private const string PackedBase64 =
        "";

    private static ushort[]? _poly;
    private static ushort[]? _vinit;

    private static void EnsureDecoded()
    {
        if (_poly is not null)
            return;
        byte[] bytes = System.Convert.FromBase64String(PackedBase64);
        var poly = new ushort[MaxDim];
        for (int i = 0; i < MaxDim; i++)
            poly[i] = (ushort)(bytes[2 * i] | (bytes[2 * i + 1] << 8));
        int vinitCount = (bytes.Length - 2 * MaxDim) / 2;
        var vinit = new ushort[vinitCount];
        for (int i = 0; i < vinitCount; i++)
            vinit[i] = (ushort)(bytes[2 * MaxDim + 2 * i] | (bytes[2 * MaxDim + 2 * i + 1] << 8));
        _vinit = vinit;
        _poly = poly;  // set last: publishes the fully-built pair.
    }

    /// <summary>The primitive polynomial for dimension <paramref name="dim" /> (0-based).</summary>
    internal static ushort Poly(int dim)
    {
        EnsureDecoded();
        return _poly![dim];
    }

    /// <summary>The flattened initial m-values (degree-many per dimension, concatenated).</summary>
    internal static ushort[] Vinit()
    {
        EnsureDecoded();
        return _vinit!;
    }
}
